//    מחלץ את ה-user_ns החדש, ובונה כתיבה של pcfCloudChatId לתיק הלקוחה
//    בפיירברי — כדי שבפעם הבאה בכלל לא נגיע לכאן.
// ============================================================================

// ==== LOGIC (pure) ====
function LOGIC(ctx) {
  const prev = ctx.prev;
  const resp = ctx.resp || {};
  const base = prev.ccBase || 'https://console.thecloud.chat/api';
  const fb = prev.fbBase || 'https://api.fireberry.com';
  const IDLE = `${base}/flow/user-fields`;
  const FB_IDLE = `${fb}/api/v3/query`;
  const FB_IDLE_BODY = { objectType: 1, fields: [{ name: 'accountid' }], pageSize: 1, pageNumber: 1 };
  const S = (v) => (v === undefined || v === null) ? '' : String(v).trim();
  const out = (o) => [{ json: Object.assign({}, prev, o) }];

  // מסלול "הכול תקין מראש" — אין יצירה, ממשיכים ישר לכתיבת השדות.
  const fieldsCall = (ns) => ({
    ccUrl: `${base}/subscriber/set-user-fields-by-name`, ccMethod: 'PUT',
    ccBody: { user_ns: ns, data: prev.fields || [] },
  });

  if (prev.ccSkip) {
    return out(Object.assign({ fbUrl: FB_IDLE, fbMethod: 'POST', fbBody: FB_IDLE_BODY },
      { ccUrl: IDLE, ccMethod: 'GET', ccBody: {} }));
  }
  if (prev.ccNeedCreate !== true) {
    return out(Object.assign({ fbUrl: FB_IDLE, fbMethod: 'POST', fbBody: FB_IDLE_BODY },
      fieldsCall(prev.userNs)));
  }

  // ---- ניתוח תשובת היצירה ----
  // {"status":"ok","data":{"inserted":1,"results":[{"user_ns":"...","phone":"+972..."}]}}
  const d = resp.data || resp || {};
  const results = Array.isArray(d.results) ? d.results
                : (Array.isArray(d.data && d.data.results) ? d.data.results : []);
  let ns = '';
  for (let i = 0; i < results.length; i++) {
    const cand = S(results[i].user_ns);
    if (cand) { ns = cand; break; }
  }
  if (!ns) ns = S(d.user_ns) || S(d.data && d.data.user_ns);

  if (!ns) {
    return out({ ccSkip: true, ccCreateFailed: true,
      ccSkipReason: 'יצירת המנויה בקלאודצ\'אט נכשלה — לא נשלחה הודעה',
      ccUrl: IDLE, ccMethod: 'GET', ccBody: {},
      fbUrl: FB_IDLE, fbMethod: 'POST', fbBody: FB_IDLE_BODY });
  }

  const o = Object.assign({ userNs: ns, ccCreated: true,
    ccWindowUnknown: true, outsideWindow: false }, fieldsCall(ns));

  // כתיבת המזהה חזרה לתיק הלקוחה — רק כשיש מזהה לקוחה.
  if (S(prev.ccAccountId)) {
    o.fbUrl = `${fb}/api/record/1/${S(prev.ccAccountId)}`;
    o.fbMethod = 'PUT';
    o.fbBody = { pcfCloudChatId: ns };
  } else {
    o.fbUrl = FB_IDLE; o.fbMethod = 'POST'; o.fbBody = FB_IDLE_BODY;
    o.ccIdNotSaved = 'אין מזהה לקוחה — המזהה בקלאודצ\'אט לא נשמר בפיירברי';
  }
  return out(o);
}

