  const displayName = cohort ? `${name} - ${cohort}` : name;

  // ── וריאציות הטלפון לחיפוש ──
  // גוגל שומר מספרים בפורמטים שונים (0533435240 / 972533435240 / +972-53-343-5240).
  // החיפוש נעשה על הספרות בלבד, וההשוואה בצד שלנו על 9 הספרות האחרונות.
  const digits = phone.replace(/\D/g, '');
  const local = digits.indexOf('972') === 0 ? '0' + digits.slice(3) : digits;
  const intl = local.indexOf('0') === 0 ? '972' + local.slice(1) : local;

  return out({
    gcSkip: false, gcSkipReason: '',
    gcQuery: local,
    gcPhoneLocal: local,
    gcPhoneIntl: '+' + intl,
    gcPhoneTail: local.slice(-9),
    gcDisplayName: displayName,
    gcGivenName: name.split(/\s+/)[0] || name,
    gcFamilyName: name.split(/\s+/).slice(1).join(' ') || cohort || '-',
    gcEmail: S(plan.email),
    gcSaleUrl: S(plan.saleId || plan.saleid) ? `https://app.fireberry.com/app/record/4/${S(plan.saleId || plan.saleid)}` : '',
    gcCohort: cohort,
  });
}

// ==== N8N BINDING ====
return LOGIC({ plan: $('בניית תוכנית מקצועית').first().json, prev: $input.first().json });

// ============================================================================
// WF-23 · הכרעה — האם ליצור איש קשר חדש
// ============================================================================

// ==== LOGIC (pure) ====
function LOGIC(ctx) {
  const prep = ctx.prep || {};
  const S = (v) => (v === undefined || v === null) ? '' : String(v).trim();
  const out = (o) => [{ json: Object.assign({}, prep, o) }];

  if (prep.gcSkip) return out({ gcCreate: false, gcFound: false });

  const resp = ctx.resp;
  // 🔴 שגיאה בחיפוש אינה "לא נמצא". יצירה על סמך חיפוש שנכשל = איש קשר כפול.
  //    השגיאה עשויה להגיע בשתי צורות: כאובייקט, או כפריט בתוך המערך —
  //    למשל rate limit: [{"error":"The service is receiving too many requests"}].
  //    נתפס חי 30/08 בזמן הבדיקות. בלי הבדיקה הזו הענף היה יוצר כפילות.
  function errOf(r) {
    if (!r) return '';
    if (Array.isArray(r)) {
      for (let i = 0; i < r.length; i++) {
        const e = r[i] && (r[i].error || (r[i].json && r[i].json.error));
        if (e) return S(typeof e === 'string' ? e : (e.message || JSON.stringify(e)));
      }
      return '';
    }
    if (r.error) return S(typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error)));
    if (r.message && !r.results) return S(r.message);
    return '';
  }
  const errText = errOf(resp);
  if (errText) {
    return out({ gcCreate: false, gcFound: false, gcSkip: true,
      gcSkipReason: 'החיפוש באנשי הקשר נכשל — לא נוצר איש קשר כדי לא לייצר כפילות: ' + errText });
  }

  const rows = Array.isArray(resp) ? resp
             : (resp && Array.isArray(resp.results)) ? resp.results
             : (resp && Array.isArray(resp.connections)) ? resp.connections
             : (resp && resp.json) ? [resp] : [];

  // 🔴 אומת חי 23/08: צומת גוגל של n8n מחזיר את הטלפונים כאובייקט לפי סוג —
  //    {"mobile":["0522283506"],"home":[...]} — ולא כמערך של {value}.
  //    גם "names" מגיע כאובייקט ולא כמערך. שתי הצורות מטופלות, אחרת ההשוואה
  //    לעולם לא תתפוס והמערכת תייצר אנשי קשר כפולים.
  function phoneDigits(p) {
    const out = [];
    const pn = p && p.phoneNumbers;
    if (!pn) return out;
    if (Array.isArray(pn)) {
      pn.forEach((x) => out.push(S(x && (x.canonicalForm || x.value || x))));
    } else if (typeof pn === 'object') {
      Object.keys(pn).forEach((k) => {
        const v = pn[k];
        if (Array.isArray(v)) v.forEach((x) => out.push(S(x && (x.value || x))));
        else out.push(S(v && (v.value || v)));
      });
    }
    return out.map((x) => x.replace(/\D/g, '')).filter(Boolean);
  }
  function displayName(p) {
    const n = p && p.names;
    if (!n) return '';
    if (Array.isArray(n)) return S(n[0] && n[0].displayName);
    return S(n.displayName || n.unstructuredName);
  }

  const tail = S(prep.gcPhoneTail);
  let matched = null;
  for (let i = 0; i < rows.length && !matched; i++) {
    const p = rows[i] && (rows[i].person || rows[i]);
    const nums = phoneDigits(p);
    for (let k = 0; k < nums.length; k++) {
      if (tail && nums[k].slice(-9) === tail) { matched = p; break; }
    }
  }

  if (matched) {
    const nm = displayName(matched);
    return out({ gcCreate: false, gcFound: true, gcExistingName: nm,
      gcSkipReason: `המספר כבר שמור באנשי הקשר${nm ? ' בשם "' + nm + '"' : ''}` });
  }
  return out({ gcCreate: true, gcFound: false });
}

// ==== N8N BINDING ====
return LOGIC({ prep: $('אנשי קשר · הכנה').first().json, resp: $input.all().map((i) => i.json) });

// ============================================================================
// WF-23 · איחוד תוצאת אנשי הקשר לשלושת המסלולים
// ============================================================================
// לצומת הזה שלושה מקורות: דילוג, "כבר קיים", ו"נוצר". הוא מנרמל את שלושתם
// לאובייקט אחד כדי שהסיכום ידווח עליהם באותה שפה.
// ============================================================================

// ==== LOGIC (pure) ====
function LOGIC(ctx) {
  const j = ctx.item || {};
  const S = (v) => (v === undefined || v === null) ? '' : String(v).trim();
  const created = !!(j.resourceName || (j.names && j.names.length));
  const gc = j.gcSkip
    ? { attempted: false, created: false, found: false, reason: S(j.gcSkipReason) }
    : (j.gcFound
        ? { attempted: true, created: false, found: true, reason: S(j.gcSkipReason), name: S(j.gcExistingName) }
        : { attempted: true, created: created, found: false,
            reason: created ? '' : 'יצירת איש הקשר לא אושרה ע"י גוגל',
            name: S(j.gcDisplayName), resourceName: S(j.resourceName) });
  const base = (j.gcSkip || j.gcCreate !== undefined) ? j : (ctx.prep || {});
  // 🔴 בתשובת גוגל אין את שדות ההכנה — השם נלקח מהצומת שהכין אותו.
  if (!gc.name && base.gcDisplayName) gc.name = S(base.gcDisplayName);
  return [{ json: Object.assign({}, base, { googleContact: gc }) }];
}

// ==== N8N BINDING ====
const j = $input.first().json || {};
let __prep = {};
try { __prep = $('אנשי קשר · הכנה').first().json || {}; } catch (e) { __prep = {}; }
return LOGIC({ item: j, prep: __prep });

// ============================================================================
// WF-2X · סיכום הריצה
// ============================================================================

// ==== LOGIC (pure) ====
function LOGIC(ctx) {
  const plan = ctx.plan;
  const parent = ctx.parent;

  const looksLikeError = (r) => {
    if (!r || typeof r !== 'object') return true;
    if (r.success === false) return true;
    if (r.Message || r.message) return true;
    if (r.error) return true;
    return false;
  };

  const results = [];
  if (!parent._noop && !parent._blocked) {
    results.push({
      wave: 1, ref: parent.ref, label: parent.label, object: parent.object, kind: parent.kind,
      ok: ctx.parentRecovered ? true : !looksLikeError(ctx.parentResp),
      recovered: !!ctx.parentRecovered, recordId: ctx.parentId || '', response: ctx.parentResp,
    });
  }
  (ctx.childReqs || []).forEach((req, i) => {
    if (!req || req._noop || req._blocked) return;
    results.push({
      wave: 2, ref: req.ref, label: req.label, object: req.object, kind: req.kind,
      ok: !looksLikeError((ctx.childResps || [])[i]), recordId: req.recordId || '',
      response: (ctx.childResps || [])[i],
    });
  });

  const failed = results.filter((r) => !r.ok);
  const parentFailed = (ctx.childReqs || []).some((r) => r && r._parentFailed);

  const cc = ctx.ccFinal || {};
  const ccResp = ctx.ccResp || {};
  const ccSent = !cc.ccSkip && (String(ccResp.status || (ccResp.data && ccResp.data.status) || '').toLowerCase() === 'ok'
                 || ccResp.success === true || !!ccResp.data);
  const wa = ctx.waFinal || {};
  const waResp = ctx.waResp || {};

  return [{
    json: {
      success: failed.length === 0 && !parentFailed,
      dryRun: plan.DRY_RUN, liveTest: plan.liveTest,
      branch: plan.branch, summary: plan.summary,
      decisions: plan.decisions, warnings: plan.warnings,
      account: { id: plan.accountid, name: plan.accountName, phone: plan.phone },
      saleid: plan.saleId, product: plan.productName,
      cohort: plan.cohortName || null, group: plan.groupName || null,
      mentoringId: ctx.parentId || plan.existingMentoringId || '',
      weeks: plan.totalWeeks || null, giftWeeks: plan.giftWeeks || 0,
      startDate: plan.startDate || null, endDate: plan.endDate || null,
      operations: results,
      failedCount: failed.length,
      parentIdMissing: !!parentFailed,
      parentRecovered: !!ctx.parentRecovered,
      welcome: {
        sent: !!ccSent,
        skipped: !!cc.ccSkip,
        reason: cc.ccSkipReason || '',
        windowUnknown: !!cc.ccWindowUnknown,
        flow: cc.flowNs || '',
      },
      whatsappGroup: {
        attempted: !wa.waSkip,
        skipped: !!wa.waSkip,
        reason: wa.waSkipReason || '',
        joined: !!(waResp && (waResp.joined === true || (waResp.data && waResp.data.joined === true))),
        groupName: wa.waGroupName || plan.groupName || '',
        inviteLink: wa.waInviteLink || '',
        response: waResp,
      },
      googleContact: ctx.googleContact || null,
      sourceExecutionUrl: plan.sourceExecutionUrl,
    },
  }];
}

// ==== N8N BINDING ====
return LOGIC({
  plan: $('בניית תוכנית מקצועית').first().json,
  parent: $('הפרדת פעולת האב').first().json,
  parentResp: $('יצירת תהליך הליווי').first().json,
