  parentRecovered: !!($('בניית פעולות המשך').first().json || {})._parentRecovered,
  childReqs: $('בניית פעולות המשך').all().map((i) => i.json),
  childResps: $('ביצוע פעולות בפיירברי').all().map((i) => i.json),
  ccFinal: $('בניית שליחת הפלואו').first().json,
